// P6 (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): the SecretProvider port and its registry, the wiring point of
// ADR-0052 §5 (REQ-S16-030 "a secret-management interface"). Owned and filled by task BE-E from here on: the built-in
// providers `env` (NAME or NAME_FILE, exactly as ADR-0011) and `file` (under SECRETS_DIR), their lines in
// packages/config/src/load.ts, and their registration on the named server.ts line. BE-A ships only the port and the
// registry, so no provider exists yet and nothing reads a secret through it; the installation behaves exactly as DG5.
// Another provider (for example Mobily IT's vault) is registered at composition by an adapter IT supplies; the product
// ships none and claims no vault integration. A value never appears in a log line, an error message or a response.

/** A reference to a secret, stored in settings instead of the value (ADR-0052 §5). */
export interface SecretRef {
  readonly provider: string;
  readonly name: string;
}

/** A resolved secret. Printing or serializing it yields the placeholder, never the value. */
export interface SecretValue {
  reveal(): string;
  toString(): "[secret]";
  toJSON(): "[secret]";
}

export interface SecretProvider {
  /** "env" (default), "file"; IT may register another. */
  readonly id: string;
  /** Never logs, never throws with the value in the message. */
  get(name: string): Promise<SecretValue | undefined>;
}

/** The provider ids ADR-0052 §5 names as built in (registered by BE-E). */
export const BUILT_IN_SECRET_PROVIDER_IDS = ["env", "file"] as const;

const PROVIDER_ID = /^[a-z][a-z0-9_-]{0,31}$/;

export interface SecretProviderRegistry {
  /** Adds a provider; a malformed or already registered id is a composition error. */
  register(provider: SecretProvider): void;
  provider(id: string): SecretProvider | undefined;
  /** The registered ids, in registration order. */
  ids(): readonly string[];
  /** Resolves a reference; an unknown provider is a configuration error that names the provider, never a value. */
  resolve(ref: SecretRef): Promise<SecretValue | undefined>;
}

export function createSecretProviderRegistry(): SecretProviderRegistry {
  const providers = new Map<string, SecretProvider>();
  return {
    register(provider) {
      if (!PROVIDER_ID.test(provider.id)) throw new Error(`secret provider id "${provider.id}" is not valid`);
      if (providers.has(provider.id)) throw new Error(`secret provider "${provider.id}" is already registered`);
      providers.set(provider.id, provider);
    },
    provider: (id) => providers.get(id),
    ids: () => [...providers.keys()],
    async resolve(ref) {
      const provider = providers.get(ref.provider);
      if (provider === undefined) throw new Error(`secret provider "${ref.provider}" is not registered`);
      return provider.get(ref.name);
    },
  };
}
// P6 route-file stub (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): the security view: the effective rate-limit classes (slice F; ADR-0052 §4).
// Owned and filled by task BE-E. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until BE-E fills it). */
export function registerSecurityRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
// P6 route-file stub (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): the global audit API, listAuditEvents and
// getAuditEvent (slice F; ADR-0052 §8). Owned and filled by task BE-E. Until then it registers nothing; its
// registration line already exists in server.ts, so the owning task edits only this file and the members of the port
// object on that line (and its own tests, pending list and contract exercises).
//
// audit cannot import access: access depends on audit (ADR-0002 rule 5; modules.ts), so the import would close a
// cycle. The authorization this file needs (the request's principal and the audit_event.read scope of ADR-0052 §8,
// with the ADR-0051 §2 sensitivity redaction) is therefore passed in by the composition root as AuditRouteAccess,
// the GateFactsProvider pattern. BE-E declares the members it uses here and fills them on the server.ts line.
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** The access functions the audit routes use, injected by server.ts (BE-E declares the members). */
export type AuditRouteAccess = Readonly<Record<string, never>>;

/** Registers this file's routes and returns them as "METHOD /path" (none until BE-E fills it). */
export function registerAuditRoutes(_app: FastifyInstance, _deps: ModuleDeps, _access: AuditRouteAccess): string[] {
  return [];
}
// audit (ADR-0004): the API's audit writer and audit queries. Depends on platform only.
//  - record(tx, ctx, event): the API's single insert path (delegates to @mth/db insertAuditEvent), always inside the
//    mutation's transaction, stamped with the request ID and source "api".
//  - listTransformationAudit: newest first, cursor on seq. Callers authorize (audit.read on the transformation).
import { insertAuditEvent, sql, type AuditEventInput, type DbOrTx, type Tx } from "@mth/db";
import type { AuditEvent } from "@mth/shared/schemas";
import { decodeCursor, filterHash, iso, paginate } from "../platform/index.ts";

export interface AuditContext {
  readonly actorUserId: string | null;
  readonly actorType?: "user" | "service" | "system";
  readonly onBehalfOfUserId?: string | null;
  readonly requestId: string;
}

export function record(tx: Tx, ctx: AuditContext, event: AuditEventInput): Promise<string> {
  return insertAuditEvent(
    tx,
    {
      actorType: ctx.actorType ?? (ctx.actorUserId ? "user" : "system"),
      actorUserId: ctx.actorUserId,
      onBehalfOfUserId: ctx.onBehalfOfUserId ?? null,
      requestId: ctx.requestId,
      source: "api",
    },
    event,
  );
}

export async function listTransformationAudit(
  db: DbOrTx,
  transformationId: string,
  page: { cursor?: string | undefined; limit: number },
): Promise<{ items: AuditEvent[]; nextCursor: string | null }> {
  const hash = filterHash({ transformationId });
  const after = decodeCursor(page.cursor, hash, 1);
  let q = db
    .selectFrom("audit_event as e")
    .leftJoin("actor_display as u", "u.user_id", "e.actor_user_id")
    .select([
      "e.id",
      "e.seq",
      "e.occurred_at",
      "e.action",
      "e.record_type",
      "e.record_id",
      "e.transformation_id",
      "e.actor_type",
      "e.actor_user_id",
      "u.display_name",
      "e.on_behalf_of_user_id",
      "e.prior_version",
      "e.new_version",
      "e.reason",
      "e.request_id",
      "e.changes",
    ])
    .where("e.transformation_id", "=", transformationId);
  if (after) q = q.where("e.seq", "<", sql<string>`${String(after[0])}::bigint`);
  const rows = await q
    .orderBy("e.seq", "desc")
    .limit(page.limit + 1)
    .execute();
  const { items, nextCursor } = paginate(rows, page.limit, (r) => [r.seq], hash);
  return {
    nextCursor,
    items: items.map((r) => ({
      id: r.id,
      seq: r.seq,
      occurredAt: iso(r.occurred_at),
      action: r.action,
      recordType: r.record_type,
      recordId: r.record_id,
      transformationId: r.transformation_id,
      actor: {
        type: r.actor_type as "user" | "service" | "system",
        userId: r.actor_user_id,
        displayName: r.display_name ?? null,
      },
      onBehalfOfUserId: r.on_behalf_of_user_id,
      priorVersion: r.prior_version,
      newVersion: r.new_version,
      reason: r.reason,
      requestId: r.request_id,
      changes: (r.changes ?? null) as AuditEvent["changes"],
    })),
  };
}

// P6 (T-DG6-BE-A stub; ADR-0052 §8): the global audit API routes (BE-E), registered by server.ts with the injected
// access port (audit cannot import access; see routes.ts).
export { registerAuditRoutes, type AuditRouteAccess } from "./routes.ts";
