// P6 stub (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): the ReadScope port, one read boundary derived from the
// ADR-0006 policy (slice E; ADR-0051 §1; REQ-S10-004). Owned and filled by task BE-B, with the parity test.
//
// The wiring point: these types are exported through access/index.ts now, so search (ADR-0057), assistant retrieval
// (ADR-0059), report and export selection (reporting/exports/jobs.ts), integrations, operations and the worker's job
// identities (ADR-0053) can be written against them; BE-B adds `readScopeFor` (a ReadScopeFactory) in this file, and
// access/index.ts already re-exports everything here. access imports none of its consumers (p6-plan §2).
import type { DbOrTx, Expression, SqlBool } from "@mth/db";
import type { Permission } from "@mth/shared";
import type { Principal } from "./policy.ts";
import type { ResolvedTarget } from "./rules.ts";

/** The record types that can be marked sensitive (D-195 Q3; the closed CHECK set of 0098, ADR-0051 §2). */
export type SensitiveRecordType = "benefit" | "business_case" | "evidence";

/** The columns of a queried row that the read decision needs (ADR-0051 §1). */
export interface ReadScopeColumns {
  /** null: a record type that cannot be sensitive. */
  readonly recordType: SensitiveRecordType | null;
  readonly recordId: Expression<string>;
  readonly organizationId: Expression<string>;
  readonly businessUnitId?: Expression<string | null>;
  readonly transformationId: Expression<string | null>;
  /** The row's named parties (ADR-0051 §2). */
  readonly partyUserIds?: readonly Expression<string | null>[];
}

/** One principal's read boundary for one permission, loaded once per request (ADR-0051 §1). */
export interface ReadScope {
  /** SQL predicate for list, search, export and retrieval queries. */
  predicate(cols: ReadScopeColumns): Expression<SqlBool>;
  /** The same decision for a row already in memory (search hits, retrieval chunks, job outputs). */
  admits(row: {
    recordType: SensitiveRecordType | null;
    recordId: string;
    target: ResolvedTarget;
    partyUserIds: readonly (string | null)[];
  }): boolean;
}

/** The signature of BE-B's `readScopeFor` (ADR-0051 §1). */
export type ReadScopeFactory = (db: DbOrTx, principal: Principal, permission: Permission) => Promise<ReadScope>;
// P6 route-file stub (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): record sensitivity flags and explicit sensitive-record grants (slice E; ADR-0051 §2).
// Owned and filled by task BE-B. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until BE-B fills it). */
export function registerSensitivityRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
// access (ADR-0006): roles, permissions, scoped assignments, delegation (table only in P1) and THE policy function.
// Depends on platform and audit only; never on a business module.
export {
  authorize,
  businessUnitAncestry,
  denialOf,
  holdsAnywhere,
  loadGrants,
  organizationsWith,
  requireAction,
  requireRead,
  resolveTarget,
  scopeFilter,
  targetFor,
  type Principal,
  type TargetRef,
} from "./policy.ts";
export {
  appliesDownward,
  decide,
  grantApplies,
  isApprovalPermission,
  STRUCTURAL_PERMISSIONS,
  type Decision,
  type DecisionContext,
  type Grant,
  type ResolvedTarget,
  type TargetLevel,
} from "./rules.ts";
export {
  activeAssignmentsOf,
  createAssignment,
  getAssignment,
  listAssignments,
  listPermissions,
  listRoles,
  revokeAssignment,
  toRoleAssignment,
  type AssignmentListQuery,
} from "./assignments.ts";
export { auditContextOf, commitTimeDenial, principalOf, refreshPrincipal, type PrincipalResolver } from "./request.ts";
export { grantCreatorAdminRoles, grantCreatorTransformationRoles } from "./assignments.ts";
export { registerDeniedMutationAudit } from "./denials.ts";
export {
  actsOnBehalfOf,
  holds,
  isOwnRow,
  requireRecordWrite,
  requireTransformationRead,
  type Ownership,
  type WriteRule,
} from "./records.ts";
export { registerAccessP2Routes } from "./team.ts";
export { registerAccessP4Routes } from "./p4-routes.ts";
// P4 slice C (T-DG4-BE-B; ADR-0026 §1-§3, §8): group membership, party routing and delegation for the approval service.
export { currentGroupMemberIds, effectiveGroupIds } from "./groups.ts";
export {
  approversOf,
  partyLabel,
  resolveParty,
  routeToParty,
  routingRefusals,
  userHoldsApprovalDecide,
  type PartyTarget,
  type RoutedParty,
} from "./role-mappings.ts";
export { actsFor, delegatorsOf } from "./delegations.ts";
// P6 slice E (T-DG6-BE-A stubs; ADR-0051 §1, §2): the ReadScope port (BE-B fills read-scope.ts; everything it exports
// is re-exported here, so later slices import it from access) and the sensitivity routes, registered by server.ts.
export * from "./read-scope.ts";
export { registerSensitivityRoutes } from "./sensitivity.ts";
// REQ-S10-003 (D-094; T-DG4-BE-B2): the technical-admin-only 403 on gate and Finance approval endpoints.
export { isTechnicalAdminOnly, TECHNICAL_ADMIN_ROLES, technicalAdminRefusal } from "./technical-admin.ts";
