    if (options.spaFallback && request.method === "GET" && !request.url.startsWith("/api/")) {
      return (reply as unknown as { sendFile(name: string): FastifyReply }).sendFile("index.html");
    }
    return sendProblem(reply, request, problems.notFound());
  });
}

