      actor: { type: "user", userId: w.office.id },
      priorVersion: 1,
      newVersion: 2,
      reason: "Synthetic visible reason",
      requestId: "audit-api-fixture",
      source: "api",
      changes: { title: { from: "Old", to: "New" } },
      redacted: false,
    });
  });
});

